import { useEffect, useRef, useState } from 'react'
import manifest from '../data/videos.json'
import { BASE, useMedia, useReducedMotion } from '../lib/env'

/**
 * Responsive ambient video (muted, looping, inline autoplay).
 * Files: public/video/<id>-{720,1080}.{webm,mp4} + <id>-poster.{webp,jpg}; metadata in src/data/videos.json
 * (generated by scripts/videos.sh). Plain files committed to git — GitHub Pages does NOT serve Git LFS.
 *
 * - 720p sources for <=768px viewports, 1080p above (chosen once on mount; no mid-play swaps)
 * - WebM (VP9) listed first, MP4 (H.264) fallback (Safari/iOS)
 * - lazy: sources attach only when within 25% of the viewport, unless `priority` (hero)
 * - pauses when offscreen or tab hidden; resumes when visible
 * - prefers-reduced-motion OR Save-Data => poster image only, no video download
 * - aspect ratio reserved from manifest => CLS 0
 */
type V = { w: number; h: number; dur: number; poster: string; sizes: Record<string, { mp4: number; webm: number }> }
const MAN = manifest as Record<string, V>

const saveData = () => !!(navigator as Navigator & { connection?: { saveData?: boolean } }).connection?.saveData

type Props = {
  id: string
  /** Accessible description of the visual (ambient video is decorative => pass '' to hide from AT). */
  label?: string
  className?: string
  videoClassName?: string
  priority?: boolean
  ratio?: number
  fit?: 'cover' | 'contain'
  /** Fill the (positioned) parent instead of reserving the clip's aspect ratio. */
  cover?: boolean
}

export default function Video({ id, label = '', className = '', videoClassName = '', priority, ratio, fit = 'cover', cover }: Props) {
  const m = MAN[id]
  const reduced = useReducedMotion()
  const small = useMedia('(max-width: 768px)')
  void small
  const [mounted, setMounted] = useState(false)
  useEffect(() => setMounted(true), [])
  // decided on the client after mount (SSR markup never carries a resolution-specific <video>)
  const res = mounted && window.matchMedia('(max-width: 768px)').matches ? '720' : '1080'
  const [near, setNear] = useState(!!priority)
  const wrap = useRef<HTMLDivElement>(null)
  const vid = useRef<HTMLVideoElement>(null)
  const posterOnly = reduced || (typeof navigator !== 'undefined' && saveData())

  // 1) Lazy attach: mount <video> only when within 25% of the viewport.
  useEffect(() => {
    const el = wrap.current
    if (!el || posterOnly || near) return
    const io = new IntersectionObserver(([e]) => e.isIntersecting && (setNear(true), io.disconnect()), { rootMargin: '25% 0px' })
    io.observe(el)
    return () => io.disconnect()
  }, [posterOnly, near])

  // 2) Once mounted: play when visible, pause offscreen / tab hidden.
  useEffect(() => {
    const el = wrap.current
    const v = vid.current
    if (!el || !v || posterOnly || !near) return
    v.muted = true // iOS autoplay requires the muted *property*; React only sets it post-mount
    v.setAttribute('muted', '')
    let inView = false
    const sync = () => (inView && !document.hidden ? v.play().catch(() => {}) : v.pause())
    const io = new IntersectionObserver(([e]) => ((inView = e.isIntersecting), sync()), { threshold: 0.01 })
    io.observe(el)
    document.addEventListener('visibilitychange', sync)
    return () => {
      io.disconnect()
      document.removeEventListener('visibilitychange', sync)
    }
  }, [posterOnly, near, mounted])

  const box = cover ? {} : { aspectRatio: ratio ? String(ratio) : m ? `${m.w} / ${m.h}` : '16 / 9' }
  if (!m)
    return <div ref={wrap} role={label ? 'img' : undefined} aria-label={label || undefined} aria-hidden={label ? undefined : true} data-video-slot={id} className={`relative max-w-full overflow-hidden bg-ink ${className}`} style={box} />

  const p = `${BASE}video/${id}`
  const poster = `${p}-poster.jpg`
  const objFit = fit === 'cover' ? 'object-cover' : 'object-contain'
  return (
    <div ref={wrap} className={`${cover ? 'absolute inset-0' : 'relative'} max-w-full overflow-hidden bg-ink ${className}`} style={box} role={label ? 'img' : undefined} aria-label={label || undefined} aria-hidden={label ? undefined : true}>
      <picture>
        <source type="image/webp" srcSet={`${p}-poster.webp`} />
        <img src={poster} alt="" width={m.w} height={m.h} loading={priority ? 'eager' : 'lazy'} decoding="async" className={`absolute inset-0 h-full w-full ${objFit}`} />
      </picture>
      {mounted && !posterOnly && near && (
        <video
          ref={vid}
          className={`absolute inset-0 h-full w-full ${objFit} ${videoClassName}`}
          poster={poster}
          muted
          loop
          playsInline
          autoPlay
          preload={priority ? 'auto' : 'metadata'}
          disablePictureInPicture
          disableRemotePlayback
          tabIndex={-1}
          data-video={id}
        >
          <source src={`${p}-${res}.webm`} type="video/webm" />
          <source src={`${p}-${res}.mp4`} type="video/mp4" />
        </video>
      )}
    </div>
  )
}
